/**
 * @fileoverview Test the usage of a removed config
 * @author Sencha
 */
'use strict';

// ------------------------------------------------------------------------------
// Requirements
// ------------------------------------------------------------------------------

const rule = require('../../../lib/rules/no-removed-config-usage'),
    RuleTester = require('eslint').RuleTester;

// ------------------------------------------------------------------------------
// Tests
// ------------------------------------------------------------------------------

const ruleTester = new RuleTester();
ruleTester.run('no-removed-config-usage', rule, {

    valid: [

    ],

    invalid: [
        {
            settings: {
                extjs: {
                    fromVersion: '4.1',
                    toVersion: '6'
                }
            },
            code: `
                var myMask = new Ext.LoadMask({
                    id: centerRegion.getId() + '-loadmask',
                    msg : 'Please wait...',
                    maskCls: 'mycustom-loadmask-mask',      // available in 4 & 5 and removed in 6
                    msgCls: 'mycustom-loadmask-msg',        // available in 4 & 5 and removed in 6
                    target : centerRegion
                });
            `,
            errors: [
                { message: /Usage of removed config 'maskCls' found for 'Ext.LoadMask'/ },
                { message: /Usage of removed config 'msgCls' found for 'Ext.LoadMask'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    fromVersion: '5',
                    toVersion: '6'
                }
            },
            code: `
                Ext.define('TreeStore', {
                    extend: 'Ext.data.TreeStore',
                    recursive: true                 // config was available in 5 and then was removed in 6
                });
            `,
            errors: [
                { message: /Usage of removed config 'recursive' found for 'Ext.data.TreeStore'/ }
            ]
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.2.6',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.define('override.AbstractView', {
                    override: 'Ext.view.AbstractView',
                    singleSelect: true
                });

                Ext.create('Ext.view.View', {
                    singleSelect: true
                });

                // TODO - how to test in a viewConfig of Ext.grid.Panel?
                // this should give an error but does not because we are not handling viewConfig
                Ext.create('Ext.grid.Panel', {
                    viewConfig: {
                        singleSelect: true
                    }
                });
            `,
            errors: [
                { message: /Usage of removed config 'singleSelect' found for 'Ext.view.AbstractView'.*/ },
                { message: /Usage of removed config 'singleSelect' found for 'Ext.view.View'.*/ }
            ]
        },
        {
            settings: {
                extjs: {
                    toolkit: 'classic',
                    fromVersion: '4.2.6',
                    toVersion: '7.9.0'
                }
            },
            code: `
                Ext.create('Ext.Container', {
                    items: [
                        {
                            xtype: 'component',
                            title: 'Tab (should auto load)',
                            autoLoad: 'resources/html/MyCustomComponent.html'
                        }
                    ]
                });
            `,
            errors: [
                { message: /Usage of removed config 'autoLoad\' found for 'Ext.Component'.*/ }
            ]
        }
    ]
});
